var salesStaff = mysqlTable2("sales_staff", {
  id: int2("id").autoincrement().primaryKey(),
  /** 关联的后台用户（可空：未开后台账号的纯销售身份），唯一 */
  adminUserId: int2("adminUserId"),
  /** 稳定工号：小写字母/数字/下划线/连字符，前台提交以此为准（姓名仅兼容） */
  staffCode: varchar2("staffCode", { length: 64 }).notNull(),
  /** 展示名（姓名） */
  displayName: varchar2("displayName", { length: 128 }).notNull(),
  status: mysqlEnum2("status", ["active", "inactive"]).default("active").notNull(),
  /** 下拉排序，升序；同值时按 id 升序 */
  sortOrder: int2("sortOrder").default(0).notNull(),
  createdAt: timestamp2("createdAt").default(DEFAULT_NOW2).notNull(),
  updatedAt: timestamp2("updatedAt").default(DEFAULT_NOW2).$onUpdate(() => /* @__PURE__ */ new Date()).notNull()
}, (table) => ({
  /**
   * 工号全局唯一。缺失会导致两人共用同一工号，
   * 商户归属同时指向两人，销售范围隔离直接失效。
   * 显式命名以与生产库索引名保持一致（不用 .unique() 自动命名）。
   */
  staffCodeUnique: uniqueIndex2("sales_staff_staff_code_unique").on(table.staffCode),
  /** 一个后台用户只能有一个销售身份；否则同一人会在下拉中重复出现、商户归属也会分叉 */
  adminUserUnique: uniqueIndex2("sales_staff_admin_user_unique").on(table.adminUserId),
  statusSortIdx: index2("sales_staff_status_sort_idx").on(table.status, table.sortOrder)
}));
