  licenseObjectKey: varchar2("licenseObjectKey", { length: 512 }),
  /** 香港 BR / CI / 银行证明私有对象键；只允许经授权的服务端短时签名。 */
  ciObjectKey: varchar2("ciObjectKey", { length: 512 }),
