  registeredCapital: varchar2("registeredCapital", { length: 64 }),
  registeredAddress: varchar2("registeredAddress", { length: 512 }),
  businessScope: text2("businessScope"),
  establishedDate: timestamp2("establishedDate"),
  legalPersonName: varchar2("legalPersonName", { length: 64 }),
  legalPersonIdNo: varchar2("legalPersonIdNo", { length: 32 }),
  legalPersonPhone: varchar2("legalPersonPhone", { length: 20 }),
  status: mysqlEnum2("status", [
    "draft",
    "pending",
    "supplement",
    "approved",
    "suspended",
    "terminated"
  ]).default("pending").notNull(),
  agreementStatus: mysqlEnum2("agreementStatus", [
    "unsigned",
    "signed",
    "expired"
  ]).default("unsigned").notNull(),
  /** 前台商家签署的协议文件 URL（PDF/图片） */
  agreementFileUrl: varchar2("agreementFileUrl", { length: 512 }),
  /** 前台商家最近一次提交入驻资料的时间 */
  submittedAt: timestamp2("submittedAt"),
  /** 资料来源：portal=前台商家提交，admin=后台录入 */
  source: varchar2("source", { length: 32 }).default("admin"),
  settlementAccount: varchar2("settlementAccount", { length: 64 }),
  settlementBank: varchar2("settlementBank", { length: 128 }),
  settlementAccountName: varchar2("settlementAccountName", { length: 128 }),
  commissionRate: decimal("commissionRate", { precision: 5, scale: 4 }).default("0.0300"),
  reviewNote: text2("reviewNote"),
  reviewedBy: int2("reviewedBy"),
  reviewedAt: timestamp2("reviewedAt"),
  /** CRM 开通状态：none=未申请 pending=待开通 enabled=已开通 disabled=已暂停 rejected=已拒绝 */
  crmStatus: mysqlEnum2("crmStatus", ["none", "pending", "enabled", "disabled", "rejected"]).default("none").notNull(),
  /** 绑定的前台账号 ID；同一统一社会信用代码只能归属一个前台账号 */
  crmOwnerPortalUserId: varchar2("crmOwnerPortalUserId", { length: 64 }),
  /** CRM 申请时间（前台提交企业开通申请时写入） */
