  /** CRM 开通时间（后台开通时写入） */
  crmEnabledAt: timestamp2("crmEnabledAt"),
  /** CRM 备注（开通/停用原因等） */
  crmNote: text2("crmNote"),
  /** 后台"发信"关联的客服会话编号（首次发信创建 service 会话后记录并复用） */
  crmThreadNo: varchar2("crmThreadNo", { length: 32 }),
