async function syncAdminUserSalesIdentity(executor, user) {
  const [linked] = await executor.select().from(salesStaff).where(eq(salesStaff.adminUserId, user.id)).limit(1);
  const shouldBeActive = user.status === "active";
  const nextStatus = shouldBeActive ? "active" : "inactive";
  const displayName = user.displayName?.trim() || user.username;
  if (linked) {
    await executor.update(salesStaff).set({ displayName, status: nextStatus }).where(eq(salesStaff.id, linked.id));
    return user.adminRole === "super_admin" ? null : linked.staffCode;
  }
  if (user.adminRole === "super_admin") return null;
  let staffCode = salesIdentityCode(user.username, user.id);
  const [sameCode] = await executor.select().from(salesStaff).where(eq(salesStaff.staffCode, staffCode)).limit(1);
  if (sameCode?.adminUserId && sameCode.adminUserId !== user.id) {
    staffCode = `user-${user.id}`;
  } else if (sameCode) {
    await executor.update(salesStaff).set({ adminUserId: user.id, displayName, status: nextStatus }).where(eq(salesStaff.id, sameCode.id));
    return staffCode;
  }
  await executor.insert(salesStaff).values({
    adminUserId: user.id,
    staffCode,
    displayName,
    status: nextStatus,
    // 自动创建的身份排在手工维护的销售之后
    sortOrder: 1e3 + user.id
  });
  return staffCode;
}
