async function listExceptionLogs(params) {
  const db = await getDb();
  if (!db) return { data: [], total: 0 };
  const { category, severity, source, ipAddress, search, from, to } = params;
  const page2 = Math.max(1, params.page ?? 1);
  const pageSize2 = Math.min(200, Math.max(1, params.pageSize ?? 50));
  const conditions = [];
  if (category) conditions.push(eq(exceptionLogs.category, category));
  if (severity) conditions.push(eq(exceptionLogs.severity, severity));
  if (source) conditions.push(eq(exceptionLogs.source, source));
  if (ipAddress) conditions.push(eq(exceptionLogs.ipAddress, ipAddress));
  if (from) conditions.push(gte(exceptionLogs.createdAt, from));
  if (to) conditions.push(lt(exceptionLogs.createdAt, to));
  if (search) {
    conditions.push(
      or(
        like(exceptionLogs.summary, `%${search}%`),
        like(exceptionLogs.path, `%${search}%`),
        like(exceptionLogs.ipAddress, `%${search}%`)
      )
    );
  }
  const where = conditions.length > 0 ? and(...conditions) : void 0;
  const [{ count: count2 }] = await db.select({ count: sql4`count(*)` }).from(exceptionLogs).where(where);
  const rows = await db.select().from(exceptionLogs).where(where).orderBy(desc(exceptionLogs.createdAt), desc(exceptionLogs.id)).limit(pageSize2).offset((page2 - 1) * pageSize2);
  return {
    data: rows.map((row) => ({
      ...row,
      detail: decodeJsonValue(row.detail)
    })),
    total: Number(count2)
  };
}
async function getExceptionLogStats() {
  const db = await getDb();
  if (!db) {
    return { last24h: [], topIps: [], total: 0 };
  }
  const since24h = new Date(Date.now() - 24 * 60 * 60 * 1e3);
  const since7d = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3);
  const byCategory = await db.select({
    category: exceptionLogs.category,
    severity: exceptionLogs.severity,
    count: sql4`count(*)`
  }).from(exceptionLogs).where(gte(exceptionLogs.createdAt, since24h)).groupBy(exceptionLogs.category, exceptionLogs.severity);
  const topIps = await db.select({
    ipAddress: exceptionLogs.ipAddress,
    ipOrigin: exceptionLogs.ipOrigin,
    count: sql4`count(*)`
  }).from(exceptionLogs).where(
    and(
      gte(exceptionLogs.createdAt, since7d),
      eq(exceptionLogs.category, "attack_probe")
    )
  ).groupBy(exceptionLogs.ipAddress, exceptionLogs.ipOrigin).orderBy(desc(sql4`count(*)`)).limit(10);
  const [{ count: total }] = await db.select({ count: sql4`count(*)` }).from(exceptionLogs);
  return {
    last24h: byCategory.map((r) => ({
      category: r.category,
      severity: r.severity,
      count: Number(r.count)
    })),
    topIps: topIps.filter((r) => r.ipAddress).map((r) => ({
      ipAddress: r.ipAddress,
      ipOrigin: r.ipOrigin,
      count: Number(r.count)
    })),
    total: Number(total)
  };
}
async function purgeExpiredExceptionLogs(retentionDays = LOG_RETENTION_DAYS) {
  const db = await getDb();
  if (!db) return 0;
  const cutoff = new Date(Date.now() - retentionDays * 24 * 60 * 60 * 1e3);
  const result = await db.execute(
    sql4`DELETE FROM exception_logs WHERE createdAt < ${cutoff}`
  );
  return Number(result[0]?.affectedRows ?? 0);
}

