        if (["CN_REVIEW_VERSION_CHANGED", "CN_REVIEW_CANDIDATE_NOT_FOUND"].includes(message)) {
          throw new TRPCError16({ code: "CONFLICT", message: "\u5F85\u5BA1\u6838\u4F01\u4E1A\u8D44\u6599\u5DF2\u53D8\u5316\uFF0C\u8BF7\u5237\u65B0\u540E\u91CD\u65B0\u6838\u5BF9" });
        }
        if (message === "CN_REVIEW_ALREADY_DECIDED") {
          throw new TRPCError16({ code: "CONFLICT", message: "\u8BE5\u7248\u672C\u5DF2\u7531\u5176\u4ED6\u5BA1\u6838\u5458\u5B8C\u6210\u4E0D\u540C\u51B3\u5B9A" });
        }
